INSERT INTO post (id, content, created_at, user_id, location_id) VALUES
(1, 'Two nomads, one shared apartment, and a surprisingly reliable fiber connection in Denpasar. This is exactly the kind of setup I came looking for.', '2026-09-20 19:00:00', 17, 1),
(2, 'Hiked out to the edge of town in Bali this morning before starting work. Nothing clears your head like a walk through a island landscape.', '2026-09-13 22:00:00', 18, 1),
(3, 'If you''re a remote worker heading to Bali, book somewhere with a balcony. The sunrise over the island is worth the early alarm.', '2026-08-29 23:00:00', 1, 1),
